REVIEW_RULE = "Only real reviews from real customers, in their words, with their permission. Never write, buy or reward reviews (in the US, the FTC's rule bans it)."
PHOTO_RULE = "Use your own photos, or ones you have permission to use. Ask customers before you show them or their home or work."
OFFER_RULE = "Say clearly what the offer is, who it is for and when it ends. Keep the terms honest and simple."


def day(theme, layout, kicker, headline, body, small, caption, alt, tip, rule="", palette="brand"):
    return {"theme": theme, "layout": layout, "kicker": kicker, "headline": headline, "body": body, "small": small,
            "caption": caption + "\n\n" + TAGS, "alt": alt, "tip": tip, "rule": rule, "palette": palette}


