def bank() -> list:
    """The 150 captions: the 30 daily ones first ('30-day plan'), then 120 more by group."""
    out = [{"cat": "30-day plan", "text": d["caption"]} for d in DAYS]
    for cat, items in BANK_GROUPS.items():
        out += [{"cat": cat, "text": t} for t in items]
    return out
